
const box=document.getElementById('article');window.readerExtract=function(html){if(typeof html!=='string'||html.length>2000000)throw Error('Article snapshot is too large');const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style,iframe,object,embed,form,link,meta,img,video,audio,source').forEach(e=>e.remove());const result=new Readability(doc,{maxElemsToParse:10000,charThreshold:100}).parse();if(!result)throw Error('No readable article found');const clean=new DOMParser().parseFromString(result.content,'text/html');const fragment=document.createDocumentFragment();const allowed=new Set(['P','H1','H2','H3','BLOCKQUOTE','UL','OL','LI','STRONG','EM','CODE','PRE','BR']);function copy(node,parent){if(node.nodeType===3){parent.append(document.createTextNode(node.textContent));return}if(node.nodeType!==1)return;const out=allowed.has(node.tagName)?document.createElement(node.tagName.toLowerCase()):document.createDocumentFragment();[...node.childNodes].forEach(child=>copy(child,out));parent.append(out)}[...clean.body.childNodes].forEach(n=>copy(n,fragment));box.replaceChildren(fragment);document.getElementById('article-title').textContent=result.title||'Article';document.getElementById('byline').textContent=result.byline||'Reader view';return{title:result.title,length:result.length}};
document.getElementById('extract').onclick=async()=>{try{const snapshot=await r2.request('reader.snapshot',{tabId:'active',maxBytes:2000000},async()=>({html:await(await fetch('sample-article.html')).text(),navigationId:'demo-nav',url:'https://example.com/article'}));window.readerExtract(snapshot.html);obUI.focus(box)}catch(e){r2.toast(e.message)}};document.getElementById('size').onchange=e=>box.style.setProperty('--reader-size',e.target.value+'px');document.getElementById('appearance').onchange=e=>{box.style.background=e.target.value==='paper'?'#f2ede1':'#0e1821';box.style.color=e.target.value==='paper'?'#17202a':'#e6edf3'};document.getElementById('exit').onclick=()=>r2.request('reader.close',{navigationId:'demo-nav'},()=>true).then(()=>r2.toast('Return requested in preview.'));const original=window.omniMediaController;window.omniMediaController=window.omniPadController=a=>{if(document.activeElement===box&&['up','down'].includes(a)){box.scrollBy({top:(a==='down'?1:-1)*200,behavior:'auto'});return true}return original(a)};
